using Servicio.RetazoMarket.Business.DTOs.MovimientoProducto;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Models;using Servicio.RetazoMarket.DataManagment.Models.Common;
namespace Servicio.RetazoMarket.Business.Services;
public class MovimientoProductoService:IMovimientoProductoService {private readonly IMovimientoProductoDataService _movimientos;private readonly IProductoDataService _productos;public MovimientoProductoService(IMovimientoProductoDataService movimientos,IProductoDataService productos)=>(_movimientos,_productos)=(movimientos,productos);public async Task<MovimientoProductoResponse?> ObtenerPorIdAsync(int id,CancellationToken ct=default){var m=await _movimientos.ObtenerPorIdAsync(id,ct);return m is null?null:MovimientoProductoBusinessMapper.ToResponse(m);}public async Task<IReadOnlyList<MovimientoProductoResponse>> ObtenerPorProductoAsync(int id,CancellationToken ct=default)=>(await _movimientos.ObtenerPorProductoAsync(id,ct)).Select(m=>MovimientoProductoBusinessMapper.ToResponse(m)).ToList();public async Task<DataPagedResult<MovimientoProductoResponse>> BuscarAsync(MovimientoProductoFiltroRequest f,CancellationToken ct=default){var e=MovimientoProductoValidator.ValidarFiltro(f);if(e.Any())throw new ValidationException("Filtro inválido.",e);var r=await _movimientos.BuscarAsync(new MovimientoProductoFiltroDataModel{id_producto=f.id_producto,tipo_movimiento=f.tipo_movimiento?.Trim().ToUpperInvariant(),motivo=f.motivo?.Trim(),fecha_desde_utc=f.fecha_desde_utc,fecha_hasta_utc=f.fecha_hasta_utc,PageNumber=f.page_number,PageSize=f.page_size},ct);return new(){Items=r.Items.Select(m=>MovimientoProductoBusinessMapper.ToResponse(m)).ToList(),PageNumber=r.PageNumber,PageSize=r.PageSize,TotalRecords=r.TotalRecords};}public async Task<MovimientoProductoResponse> CrearAsync(CrearMovimientoProductoRequest r,CancellationToken ct=default){var e=MovimientoProductoValidator.ValidarCreacion(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);var producto=await _productos.ObtenerPorIdAsync(r.id_producto,ct)??throw new ValidationException("El producto no existe.");var tipo=r.tipo_movimiento.Trim().ToUpperInvariant();int stock;try{stock=MovimientoProductoValidator.CalcularStock(producto.stock_actual,tipo,r.cantidad);}catch(OverflowException){throw new ValidationException("El stock resultante excede el rango permitido.");}if(stock<0)throw new ValidationException("El movimiento produciría stock negativo.");var creado=await _movimientos.CrearConActualizacionStockAsync(MovimientoProductoBusinessMapper.ToDataModel(r),stock,ct)??throw new ValidationException("No se pudo actualizar el producto.");return MovimientoProductoBusinessMapper.ToResponse(creado,stock);}}
